import requests

params = {}
def _build_url(path, **params):
    """
    Build a URL with the provided path and parameters
    """
    params = parse_qs(params)
    query_string = urllib.parse.urlencode(params)
    return '{}?{}'.format(base_url + path, query_string)

def _send_request(path, params, method, headers=None):
    url = _build_url(path, **params)
    response = requests.request(method, url, headers=headers)
    return response

def get(path, params=None, **kwargs):
    if params is None:
        params = {}
    kwargs = dict(params=params, **kwargs)
    return _send_request(path, **kwargs)

def post(path, params={}, **kwargs):
    return _send_request(path, params, method='POST', **kwargs)

def put(path, params={}, **kwargs):
    return _send_request(path, params, method='PUT', **kwargs)

def delete(path, params={}, **kwargs):
    return _send_request(path, params, method='DELETE', **kwargs)

def patch(path, params={}, **kwargs):
    return _send_request(path, params, method='PATCH', **kwargs)

