from geopy.geocoders import Nominatim

app = Flask(__name__)
geolocator = Nominatim()

@app.route('/')
def welcome():
    return "Welcome to Geopositioning service!"

@app.route('/geocode', methods=['POST'])
def geocode():
    addr = request.json.get('address')
    location = geolocator.geocode(addr)

    if not location:
        return jsonify({
            "status": "error",
            "message": "Address not found."
        })

    coords = {
        'latitude': location.latitude,
        'longitude': location.longitude
    }

    response = jsonify({
        "coordinates": coords,
        "location": location.address
    })

    return response

@app.route('/reverse_geocode', methods=['POST'])
def reverse_geocode():
    lat = float(request.json.get('lat'))
    lon = float(request.json.get('lon'))

    location = geolocator.reverse((lat, lon))

    if not location:
        return jsonify({
            "status": "error",
            "message": "Location not found."
        })

    response = jsonify({
        "label": location.raw.get('display_name'),
        "point": {'lat': lat, 'lon': lon}
    })

    return response

if __name__ == '__main__':
    app.run(debug=True)

