from typing import List

def is_vowel(char: str) -> bool:
    vowels = "aeiouAEIOU"
    return char in vowels

def count_vowels_in_list(word_list: List[str]) -> int:
    count = 0
    for word in word_list:
        for char in word:
            if is_vowel(char):
                count += 1
    return count

