BLOCK_DELIM = '\n---\n'

def parse_rules(rule_str: str) -> list[tuple[str, int, Optional[str]]]:
    rules = rule_str.split(BLOCK_DELIM)
    rules = [r.strip() for r in rules if r.strip()] + [['ANY', 100]]
    return [r.split() for r in rules]

class Sorter:
    def __init__(self):
        self.rules = []
        self.ruleset = None

    def train(self, rule_str: str):
        self.rules = parse_rules(rule_str)
        self.ruleset = {}
        for r in self.rules:
            self.ruleset.setdefault(r[0], []).append((r[1], r[2]))

    def sort(self, items):
        return sorted(items, key=self.score, reverse=True)

    def score(self, item):
        scores = [(0 if score is None else score, r) for score, r in self.rules]
        scores.sort()
        return max(s[0] for s in scores)

    def predict_rule(self, item):
        candidates = {}
        for name, rules in self.ruleset.items():
            for priority, regex in rules:
                if regex and re.fullmatch(regex, item):
                    if name not in candidates or priority > candidates[name]:
                        candidates[name] = priority
        return max(candidates.items(), key=lambda x: x[1])[0]

