import pickle
from collections import defaultdict

class Menu:
    def __init__(self, ingredients):
        self.ingredients = ingredients
        self.used_ingredients = defaultdict(int)

    def add_ingredient(self, ingredient):
        if ingredient in self.ingredients:
            self.used_ingredients[ingredient] += 1

    def get_ingredient_count(self, ingredient):
        if ingredient in self.used_ingredients:
            return self.used_ingredients[ingredient]
        else:
            return 0

    def __str__(self):
        return 'Total ingredients: ' + str(sum(self.used_ingredients.values()))

class Order:
    def __init__(self, menu, dish):
        self.menu = menu
        self.dish = dish

    def fulfill(self):
        self.menu.add_ingredient(self.dish)

    def __str__(self):
        return 'Order: ' + self.dish

