import pickle
import subprocess
import os

def clean_up_files(prefix):
    for f in os.listdir('.'):
        if f.startswith(prefix):
            os.remove(f)

def save_file(name, data):
    tmp_file = name + '.tmp'
    with open(tmp_file, 'wb') as f:
        pickle.dump(data, f)
    os.rename(tmp_file, name)
    os.chmod(name, 0o777)

def get_file(name):
    tmp_file = name + '.tmp'
    with open(name, 'rb') as f:
        data = pickle.load(f)
        os.remove(name)
    save_file(tmp_file, data)
    return f.readlines(tmp_file)

def main():
