from typing import Tuple

def calculate_discriminant(a: float, b: float, c: float) -> Tuple[int, str, float]:
    discriminant = b**2 - 4*a*c

    if discriminant > 0:
        message = 'Two distinct real number solutions.'
        result = (2, message, discriminant)
    elif discriminant == 0:
        message = 'One solution.'
        result = (2, message, discriminant)
    else:
        message = 'No real number solutions.'
        result = (2, message, discriminant)

    return result

