from collections import defaultdict

class Employee:
    def __init__(self, name, gender, salary):
        self.name = name
        self.gender = gender
        self.salary = salary

    @property
    def salary(self):
        return self._salary

    @salary.setter
    def salary(self, value):
        self._salary = value

    def __repr__(self):
        return f"Employee(name={self.name}, gender={self.gender}, salary={self.salary})"

def get_average_salary(employees):
    return sum(employee.salary for employee in employees) / len(employees)

