from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/get_jobs', methods=['GET'])
def get_jobs():
    keywords = request.args.get('keywords', '')

    if not keywords:
        return jsonify({'error': 'No keywords provided'})

    companies = ['Google', 'Microsoft', 'Apple']

    jobs = []
    for company in companies:
        company = {'company': company, 'jobs': []}

        for keyword in keywords.split():
            jobs.extend([
                {'title': f'Job {i} at {company}' + ' for ' + keyword,
                 'company': company,
                 'location': f'New York, NY'}
                for i in range(1, 10)])

        company['jobs'] = jobs
        jobs.append(company)

    return jsonify(jobs)

